const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * A small error type used for all "usage"/"line N"/"unknown task" failures,
 * i.e. everything reported on stderr with exit code 2.
 */
export class ParseError extends Error {}

/**
 * Thrown when a cycle is detected. `cycle` is the array of names describing
 * the cycle, already ending with a repeat of its first name.
 */
export class CycleError extends Error {
  constructor(cycle) {
    super(`cycle: ${cycle.join(' -> ')}`)
    this.cycle = cycle
  }
}

function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Parses the raw input text into a graph: a map of task name -> cost, and a
 * map of task name -> Set of dependency names.
 */
export function parseGraph(input) {
  const lines = splitLines(input)
  const tasks = new Map() // name -> cost
  const deps = new Map() // name -> Set(name)
  const depUsages = [] // flat list of names used by dep lines, in order

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new ParseError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const name = words[1]
      const costWord = words[2]
      if (!NAME_RE.test(name)) {
        throw new ParseError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costWord)) {
        throw new ParseError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new ParseError(`line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costWord, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new ParseError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const from = words[1]
      const rest = words.slice(2)
      if (!NAME_RE.test(from)) {
        throw new ParseError(`line ${lineNo}: invalid task name ${from}`)
      }
      for (const dep of rest) {
        if (!NAME_RE.test(dep)) {
          throw new ParseError(`line ${lineNo}: invalid task name ${dep}`)
        }
      }
      depUsages.push(from)
      for (const dep of rest) depUsages.push(dep)
      if (!deps.has(from)) deps.set(from, new Set())
      const set = deps.get(from)
      for (const dep of rest) set.add(dep)
    } else {
      throw new ParseError(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of depUsages) {
    if (!tasks.has(name)) {
      throw new ParseError(`unknown task ${name}`)
    }
  }

  return { tasks, deps }
}

/**
 * Finds the first cycle a depth-first search encounters, starting from each
 * task in ascending name order and walking each task's dependencies in
 * ascending name order. Returns null when the graph is acyclic.
 */
export function findCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const state = new Map() // 0/absent = unvisited, 1 = in-stack, 2 = done
  const stack = []

  function dfs(u) {
    state.set(u, 1)
    stack.push(u)
    const depNames = [...(deps.get(u) || [])].sort()
    for (const v of depNames) {
      const st = state.get(v) || 0
      if (st === 1) {
        const idx = stack.indexOf(v)
        return stack.slice(idx).concat(v)
      } else if (st === 0) {
        const found = dfs(v)
        if (found) return found
      }
    }
    stack.pop()
    state.set(u, 2)
    return null
  }

  for (const name of names) {
    if ((state.get(name) || 0) === 0) {
      const found = dfs(name)
      if (found) return found
    }
  }
  return null
}
"}

