{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-PJ9MRA/src/schedule.js","content":"// Computations over an already-parsed, acyclic build graph.

/**
 * Computes, for every task, its start, finish and depth (wave), assuming an
 * unlimited number of workers. Returns a Map name -> { start, finish, depth }.
 */
export function computeTimings(tasks, deps) {
  const result = new Map()

  function compute(name) {
    if (result.has(name)) return result.get(name)
    const cost = tasks.get(name)
    const depNames = [...(deps.get(name) || [])]
    let start = 0
    let depth = 0
    for (const dep of depNames) {
      const info = compute(dep)
      if (info.finish > start) start = info.finish
      if (info.depth + 1 > depth) depth = info.depth + 1
    }
    const finish = start + cost
    const info = { start, finish, depth }
    result.set(name, info)
    return info
  }

  for (const name of tasks.keys()) compute(name)
  return result
}

/**
 * Computes the priority of every task used by `pack`: the cost of the
 * longest chain starting at the task and following dependencies down to a
 * task with none.
 */
export function computePriorities(tasks, deps) {
  const result = new Map()

  function compute(name) {
    if (result.has(name)) return result.get(name)
    const cost = tasks.get(name)
    const depNames = [...(deps.get(name) || [])]
    let maxDep = 0
    for (const dep of depNames) {
      const p = compute(dep)
      if (p > maxDep) maxDep = p
    }
    const priority = cost + maxDep
    result.set(name, priority)
    return priority
  }

  for (const name of tasks.keys()) compute(name)
  return result
}

/**
 * Simulates the graph on `workerCount` workers using the priority list
 * scheduling rule described in the spec. Returns { workers, makespan } where
 * `workers` is an array (index = worker id) of { name, start, finish } runs.
 */
export function pack(tasks, deps, workerCount) {
  const names = [...tasks.keys()].sort()
  const priorities = computePriorities(tasks, deps)

  // dependents[name] = list of tasks that depend on `name`.
  const dependents = new Map()
  for (const name of names) dependents.set(name, [])
  for (const [from, set] of deps) {
    for (const dep of set) {
      if (!dependents.has(dep)) dependents.set(dep, [])
      dependents.get(dep).push(from)
    }
  }

  const indegree = new Map()
  for (const name of names) indegree.set(name, (deps.get(name) || new Set()).size)

  const finishTime = new Map()
  const pendingReady = new Map() // name -> ready-not-before time
  for (const name of names) {
    if (indegree.get(name) === 0) pendingReady.set(name, 0)
  }

