/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import fs from 'node:fs'
import { parseGraph, findCycle, ParseError } from './parse.js'
import { computeTimings, pack } from './schedule.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function fail(message, code) {
  process.stderr.write(message + '\n')
  process.exit(code)
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      fail('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  fail(USAGE, 2)
}

function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)

  const input = fs.readFileSync(0, 'utf8')

  let tasks, deps
  try {
    ;({ tasks, deps } = parseGraph(input))
  } catch (err) {
    if (err instanceof ParseError) {
      fail(`error: ${err.message}`, 2)
    }
    throw err
  }

  const cycle = findCycle(tasks, deps)
  if (cycle) {
    fail(`error: cycle: ${cycle.join(' -> ')}`, 3)
  }

  const names = [...tasks.keys()].sort()

  if (args.mode === 'waves') {
    const timings = computeTimings(tasks, deps)
    const waves = []
    for (const name of names) {
      const depth = timings.get(name).depth
      if (!waves[depth]) waves[depth] = []
      waves[depth].push(name)
    }
    let total = 0
    for (const info of timings.values()) {
      if (info.finish > total) total = info.finish
    }
    const lines = []
    for (let k = 0; k < waves.length; k++) {
      const group = (waves[k] || []).slice().sort()
      lines.push(`wave ${k}: ${group.join(' ')}`)
    }
    lines.push(`total ${total}`)
    process.stdout.write(lines.join('\n') + '\n')
    return
  }

  if (args.mode === 'explain') {
    const timings = computeTimings(tasks, deps)
    let total = 0
    for (const info of timings.values()) {
      if (info.finish > total) total = info.finish
    }
    const lines = []
    for (const name of names) {
      const info = timings.get(name)
      lines.push(`${name} start=${info.start} finish=${info.finish} depth=${info.depth}`)
    }
    lines.push(`total ${total}`)
    process.stdout.write(lines.join('\n') + '\n')
    return
  }

  if (args.mode === 'pack') {
    const { workers, makespan } = pack(tasks, deps, args.workers)
    const lines = []
    for (let i = 0; i < workers.length; i++) {
      const runs = workers[i].map((r) => ` ${r.name}@${r.start}-${r.finish}`).join('')
      lines.push(`worker ${i}:${runs}`)
    }
    lines.push(`makespan ${makespan}`)
    process.stdout.write(lines.join('\n') + '\n')
    return
  }
}

main()
"}

